        return FrameTransform(self.source, after.target,
                              self.unit, after.matrix @ self.matrix)

"""A small, dependency-light laboratory for vectors, frames, and transforms.

The module is intentionally explicit about semantic information that a bare
``numpy.ndarray`` cannot carry: source frame, target frame, and length unit.
It is used by Chapter 2 of the integrated robotics research textbook.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable

import numpy as np


Array = np.ndarray


class FrameError(ValueError):
    """Raised when a frame or geometric-object contract is violated."""


def _array2(value: Iterable[float], *, name: str) -> Array:
    array = np.asarray(value, dtype=float)
    if array.shape != (2,):
        raise FrameError(f"{name} must have shape (2,), got {array.shape}")
    if not np.all(np.isfinite(array)):
        raise FrameError(f"{name} must contain finite values")
    return array


def rotation(theta_rad: float) -> Array:
    """Return a 2-D counter-clockwise rotation matrix."""

    theta_rad = float(theta_rad)
    if not np.isfinite(theta_rad):
        raise FrameError("theta_rad must be finite")
    c, s = np.cos(theta_rad), np.sin(theta_rad)
    return np.array([[c, -s], [s, c]], dtype=float)


def homogeneous(rotation_matrix: Array, translation: Iterable[float]) -> Array:
    """Build a 3-by-3 planar homogeneous transform."""

    r = np.asarray(rotation_matrix, dtype=float)
    t = _array2(translation, name="translation")
    if r.shape != (2, 2):
        raise FrameError(f"rotation_matrix must have shape (2, 2), got {r.shape}")
    if not np.allclose(r.T @ r, np.eye(2), atol=1e-9):
        raise FrameError("rotation_matrix is not orthonormal")
    if not np.isclose(np.linalg.det(r), 1.0, atol=1e-9):
        raise FrameError("rotation_matrix must have determinant +1")
    return np.block([[r, t[:, None]], [np.zeros((1, 2)), np.ones((1, 1))]])


@dataclass(frozen=True)
class FrameTransform:
    """A transform mapping coordinates from ``source`` to ``target``.

    ``matrix`` is a 3-by-3 planar homogeneous transform.  The semantic
    direction is part of the object, so composition can reject a physically
    invalid chain even when the raw matrix multiplication is dimensionally
    legal.
    """

    source: str
    target: str
    unit: str
    matrix: Array

    def __post_init__(self) -> None:
        if not all(isinstance(value, str) and value for value in (self.source, self.target, self.unit)):
            raise FrameError("source, target, and unit must be non-empty strings")
        matrix = np.asarray(self.matrix, dtype=float)
        if matrix.shape != (3, 3):
            raise FrameError(f"matrix must have shape (3, 3), got {matrix.shape}")
        if not np.all(np.isfinite(matrix)):
            raise FrameError("matrix must contain finite values")
        if not np.allclose(matrix[2], [0.0, 0.0, 1.0], atol=1e-9):
            raise FrameError("the last row must be [0, 0, 1]")
        r = matrix[:2, :2]
        if not np.allclose(r.T @ r, np.eye(2), atol=1e-9):
            raise FrameError("the rotation block must be orthonormal")
        if not np.isclose(np.linalg.det(r), 1.0, atol=1e-9):
            raise FrameError("the rotation block must have determinant +1")
        object.__setattr__(self, "matrix", matrix)

    @classmethod
    def from_angle_translation(
        cls, source: str, target: str, unit: str, theta_rad: float, translation: Iterable[float]
    ) -> "FrameTransform":
        return cls(source, target, unit, homogeneous(rotation(theta_rad), translation))

    def apply_point(self, point: Iterable[float]) -> Array:
        """Transform a point; translation is intentionally included."""

        p = _array2(point, name="point")
        return (self.matrix @ np.r_[p, 1.0])[:2]

    def apply_vector(self, vector: Iterable[float]) -> Array:
        """Transform a free vector; translation must not affect it."""

        v = _array2(vector, name="vector")
        return (self.matrix[:2, :2] @ v)

    def inverse(self) -> "FrameTransform":
        """Return the inverse transform with swapped semantic direction."""

        r = self.matrix[:2, :2]
        t = self.matrix[:2, 2]
        inverse_matrix = homogeneous(r.T, -(r.T @ t))
        return FrameTransform(self.target, self.source, self.unit, inverse_matrix)

    def then(self, after: "FrameTransform") -> "FrameTransform":
        """Apply this transform first, then ``after``."""

        if self.target != after.source:
            raise FrameError(
                f"cannot compose {self.source}->{self.target} with "
                f"{after.source}->{after.target}: intermediate frames differ"
            )
        if self.unit != after.unit:
            raise FrameError(f"unit mismatch: {self.unit!r} versus {after.unit!r}")
        return FrameTransform(
            self.source,
            after.target,
            self.unit,
            after.matrix @ self.matrix,
        )


def fit_rigid_2d(source_points: Array, target_points: Array, *, unit: str = "m") -> FrameTransform:
    """Estimate a planar rigid transform with the Kabsch/SVD construction.

    The point arrays have shape ``(n, 2)`` and are paired row by row.  The
    function is deliberately small enough to inspect, but it still handles
    reflection and reports degenerate input instead of silently returning a
    numerically meaningless pose.
    """

    source = np.asarray(source_points, dtype=float)
    target = np.asarray(target_points, dtype=float)
    if source.ndim != 2 or source.shape[1] != 2:
        raise FrameError(f"source_points must have shape (n, 2), got {source.shape}")
    if target.shape != source.shape or len(source) < 3:
        raise FrameError("paired point arrays must share shape and contain at least three points")
    if not np.all(np.isfinite(source)) or not np.all(np.isfinite(target)):
        raise FrameError("calibration points must be finite")

    source_center = source.mean(axis=0)
    target_center = target.mean(axis=0)
    centered_source = source - source_center
    centered_target = target - target_center
    if np.linalg.matrix_rank(centered_source, tol=1e-12) < 2 or np.linalg.matrix_rank(centered_target, tol=1e-12) < 2:
        raise FrameError("calibration points must span two independent directions")
    covariance = centered_source.T @ centered_target
    u, singular_values, vt = np.linalg.svd(covariance)
    if singular_values[-1] < 1e-12:
        raise FrameError("calibration geometry is degenerate")
    correction = np.eye(2)
    if np.linalg.det(vt.T @ u.T) < 0.0:
        correction[-1, -1] = -1.0
    r = vt.T @ correction @ u.T
    t = target_center - r @ source_center
    return FrameTransform("source", "target", unit, homogeneous(r, t))


def calibration_rmse(transform: FrameTransform, source_points: Array, target_points: Array) -> float:
    """Return the root-mean-square point error in the declared unit."""

    source = np.asarray(source_points, dtype=float)
    target = np.asarray(target_points, dtype=float)
    if source.ndim != 2 or source.shape[1:] != (2,) or target.shape != source.shape or len(source) == 0:
        raise FrameError("source and target must be non-empty paired (n, 2) arrays")
    if not np.all(np.isfinite(source)) or not np.all(np.isfinite(target)):
        raise FrameError("RMSE points must be finite")
    predicted = np.vstack([transform.apply_point(p) for p in source])
    return float(np.sqrt(np.mean(np.sum((predicted - target) ** 2, axis=1))))


def run_calibration_demo(seed: int = 7, noise_std: float = 0.002) -> dict[str, float]:
    """Run a deterministic noisy calibration experiment and return metrics."""

    if isinstance(seed, (bool, np.bool_)) or not isinstance(seed, (int, np.integer)):
        raise FrameError("seed must be an integer")
    noise_std = float(noise_std)
    if not np.isfinite(noise_std) or noise_std < 0:
        raise FrameError("noise_std must be finite and non-negative")
    rng = np.random.default_rng(int(seed))
    source = np.array([[0.0, 0.0], [0.30, 0.02], [0.06, 0.25], [0.22, 0.31]])
    truth = FrameTransform.from_angle_translation(
        "camera", "base", "m", np.deg2rad(27.0), [0.42, -0.18]
    )
    target_clean = np.vstack([truth.apply_point(p) for p in source])
    target_noisy = target_clean + rng.normal(0.0, noise_std, size=target_clean.shape)
    estimate = fit_rigid_2d(source, target_noisy, unit="m")
    return {
        "seed": float(seed),
        "noise_std_m": float(noise_std),
        "fit_rmse_m": calibration_rmse(estimate, source, target_noisy),
        "truth_rmse_m": calibration_rmse(truth, source, target_noisy),
        "translation_error_m": float(np.linalg.norm(estimate.matrix[:2, 2] - truth.matrix[:2, 2])),
        "rotation_error_rad": float(
            np.arccos(np.clip((np.trace(estimate.matrix[:2, :2].T @ truth.matrix[:2, :2]) - 0.0) / 2.0, -1.0, 1.0))
        ),
    }


if __name__ == "__main__":
    metrics = run_calibration_demo()
    for key, value in metrics.items():
        print(f"{key}: {value:.8f}" if isinstance(value, float) else f"{key}: {value}")
